import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Troubleshooting","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/troubleshooting.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","filePath":"packages/distant-horizons-support-pumpkin/docs/troubleshooting.md","lastUpdated":1792508900000}`),a={name:`packages/distant-horizons-support-pumpkin/docs/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h1><h2 id="the-client-disconnects-or-never-opens-a-session" tabindex="-1">The client disconnects or never opens a session <a class="header-anchor" href="#the-client-disconnects-or-never-opens-a-session" aria-label="Permalink to “The client disconnects or never opens a session”">​</a></h2><p>Check the plugin README for the supported Distant Horizons release and make sure the client is running it. If the protocol versions differ, the plugin closes the session and logs a warning with the client&#39;s and the server&#39;s protocol numbers. Only Java Edition players can open Distant Horizons sessions.</p><p>Worlds in a custom dimension need a height in the plugin config. Without one, the plugin closes DH sessions in that world and logs the <code>[worlds.&quot;&lt;world&gt;&quot;]</code> key to add once per world.</p><h2 id="requests-stay-pending-because-terrain-is-unavailable" tabindex="-1">Requests stay pending because terrain is unavailable <a class="header-anchor" href="#requests-stay-pending-because-terrain-is-unavailable" aria-label="Permalink to “Requests stay pending because terrain is unavailable”">​</a></h2><p>The plugin can read only chunks Pumpkin has loaded; it cannot load or generate them. If the requested area isn&#39;t loaded and has no cached capture, the request stays pending while the plugin checks again with increasing delays. Bring the area within range of a player or use a server chunk-loading tool. The client can cancel a request it no longer needs, and each pending request uses space in the configured queue. See the plugin README for the section size and capture requirements.</p><h2 id="a-client-sees-old-terrain" tabindex="-1">A client sees old terrain <a class="header-anchor" href="#a-client-sees-old-terrain" aria-label="Permalink to “A client sees old terrain”">​</a></h2><p>The plugin keeps serving a cached capture until it reaches its configured refresh age. It rebuilds an expired capture in the background when the server has the terrain loaded; otherwise, the older capture remains available. Blocks placed or broken by players, crop growth and fire spread clear the affected captures right away. Other changes can show up only after a later refresh. To rebuild one wrong section now, use <code>/dhs cache recover &lt;x&gt; &lt;z&gt;</code> as described in <a href="./cache#rebuild-one-wrong-section">Manage the LOD cache</a>.</p><p>If you replace world data or change a dimension&#39;s height, stop the server, remove this plugin&#39;s <code>cache/</code> folder, and restart the server.</p><h2 id="requests-stay-queued-or-progress-is-slow" tabindex="-1">Requests stay queued or progress is slow <a class="header-anchor" href="#requests-stay-queued-or-progress-is-slow" aria-label="Permalink to “Requests stay queued or progress is slow”">​</a></h2><p>Run <code>/dhs status</code> to see worker ticks, capture progress, the capture budget, Pumpkin&#39;s reported MSPT, queued responses and their bytes, DH packet bytes sent, and the served, rejected and cancelled request counts. The counts start at zero when the plugin loads.</p><ul><li>If worker ticks stay at zero, the plugin&#39;s tick handler isn&#39;t running. Check the server log for plugin errors.</li><li>If worker ticks and capture progress keep rising, the plugin is working through the queue. The client can keep adding requests while it does.</li><li>If rejections rise with <code>Chunk ... is not loaded</code>, the requested terrain is still unavailable. See <a href="#requests-stay-pending-because-terrain-is-unavailable">Requests stay pending because terrain is unavailable</a>.</li><li>If the last rejection is <code>LOD request limit reached</code>, the request queue is full. It drains as captures finish, or you can raise <code>pending_requests</code>.</li><li>If cancellations rise, the client is dropping requests it no longer needs.</li></ul><p>The capture budget shrinks as the server gets busier and drops to zero when Pumpkin reports 45 MSPT or more. Cached sections still go out while sampling is paused, including during a forced capture. On the pinned Pumpkin release, the reported MSPT doesn&#39;t include this plugin&#39;s own tick handler, so <code>/dhs status</code> also shows how long that handler took last tick.</p><p>The client&#39;s ETA counts time since the request was sent, including time in the queue, so it doesn&#39;t measure network speed. A nonzero client bandwidth limit paces outgoing fragments, and zero means unlimited. The defaults for the queue and transfer settings in the plugin README are provisional until they have been measured on real servers.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};